      "ipcCode": "",
      "fTerm": "TREATMENT OF WATER, WASTE WATER, SEWAGE, OR SLUDGE (processes for making harmful chemical substances harmless, or less harmful, by effecting a chemical change in the substances <b>A62D 3/00</b>; separation, settling tanks or filter devices  <b>B01D</b>; special arrangements on waterborne vessels of installations for treating water, waste water or sewage, e.g. for producing fresh water, <b>B63J</b>; adding materials to water to prevent corrosion <b>C23F</b>; treating radioactively-contaminated liquids <b>G21F 9/04</b>)<b>[3]</b><br><br><b><u>Note(s)</u></b><br><br><ul type=\"\"1\"\"><li>When classifying in this subclass, classification is also made in group <b>B01D 15/08</b> insofar as subject matter of general interest relating to chromatography is concerned.<b>[7,8]</b></li><li>In this subclass, it is desirable to add the indexing codes of groups <b>C02F 101/00</b> or <b>C02F 103/00</b>.</li></ul><br><br><b><u>Subclass indexes</u></b><br><table width=\"100%\"><tr><td width=\"70%\"><p style=\"\"text-indent:1em;margin:0\"\">CHEMICAL OR PHYSICAL TREATMENT</td><td><b>1/00</b>, <b>5/00</b></td></p></tr><tr><td width=\"70%\"><p style=\"\"text-indent:1em;margin:0\"\">BIOLOGICAL TREATMENT</td><td><b>3/00</b></td></p></tr><tr><td width=\"70%\"><p style=\"\"text-indent:1em;margin:0\"\">AERATION OF STRETCHES</td><td><b>7/00</b></td></p></tr><tr><td width=\"70%\"><p style=\"\"text-indent:1em;margin:0\"\">MULTISTAGE TREATMENT</td><td><b>9/00</b></td></p></tr><tr><td width=\"70%\"><p style=\"\"text-indent:1em;margin:0\"\">TREATMENT OF SLUDGE</td><td><b>11/00</b></td></p></tr></table>",
